// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawCalls) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1 ether);
        vm.assume(withdrawCalls >= 1 && withdrawCalls <= 10);

        address user = address(0x1000);
        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        for (uint256 i = 0; i < withdrawCalls; i++) {
            vm.prank(user);
            c.withdrawAll();
        }

        uint256 balanceAfter = address(c).balance;
        uint256 balanceDrop = balanceBefore - balanceAfter;
        assertTrue(balanceDrop <= depositAmount);
    }
}
